/* Northwake. Tokens: see DESIGN.md */
:root {
  --bg: oklch(0.17 0.02 265);
  --surface: oklch(0.21 0.025 265);
  --ink: oklch(0.95 0.012 80);
  --muted: oklch(0.76 0.02 265);
  --dawn: oklch(0.82 0.11 60);
  --line: oklch(0.52 0.04 265);
  --rule: oklch(0.32 0.025 265);

  --display: "Young Serif", Georgia, serif;
  --body: "Hanken Grotesk", system-ui, sans-serif;

  --ease: cubic-bezier(0.22, 1, 0.36, 1); /* ease-out quint */
  --z-sticky: 10;
  --gutter: clamp(1.25rem, 5vw, 4rem);
}

*, *::before, *::after { box-sizing: border-box; }
html { scroll-behavior: smooth; scroll-padding-top: 5rem; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font: 400 1.0625rem/1.65 var(--body);
  -webkit-font-smoothing: antialiased;
}
h1, h2 { font-family: var(--display); font-weight: 400; text-wrap: balance; margin: 0; }
p { margin: 0; text-wrap: pretty; }
a { color: inherit; }

:focus-visible { outline: 2px solid var(--dawn); outline-offset: 3px; border-radius: 4px; }

.skip {
  position: absolute; left: 1rem; top: -4rem; z-index: calc(var(--z-sticky) + 1);
  background: var(--dawn); color: var(--bg); padding: 0.6rem 1rem; border-radius: 6px; font-weight: 600;
}
.skip:focus { top: 1rem; }

/* Buttons & links */
.btn {
  display: inline-flex; align-items: center; min-height: 3rem; padding: 0 1.5rem;
  background: var(--dawn); color: var(--bg); border-radius: 999px;
  font-weight: 600; text-decoration: none;
  transition: background-color 200ms var(--ease), transform 200ms var(--ease);
}
.btn:hover { background: oklch(0.88 0.09 65); }
.btn:active { transform: scale(0.97); }
.btn--small { min-height: 2.75rem; padding: 0 1.1rem; font-size: 0.9375rem; }
.link {
  display: inline-flex; align-items: center; min-height: 3rem;
  color: var(--muted); text-underline-offset: 0.3em; text-decoration-color: var(--line);
}
.link:hover { color: var(--ink); text-decoration-color: var(--dawn); }

/* Nav: frosted, stays at the top */
.nav {
  position: sticky; top: 0; z-index: var(--z-sticky);
  background: oklch(0.17 0.02 265 / 0.92);
  border-bottom: 1px solid oklch(0.95 0.012 80 / 0.08);
}
@supports (backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px)) {
  .nav {
    background: oklch(0.17 0.02 265 / 0.55);
    -webkit-backdrop-filter: blur(16px) saturate(1.4);
    backdrop-filter: blur(16px) saturate(1.4);
  }
}
.nav__inner {
  display: flex; align-items: center; justify-content: space-between; gap: 1rem;
  max-width: 76rem; margin: 0 auto; padding: 0.5rem var(--gutter);
}
.wordmark {
  display: inline-flex; align-items: center; gap: 0.6rem; min-height: 2.75rem;
  font: 400 1.25rem/1 var(--display); text-decoration: none;
}
.wordmark__mark { width: 1.6rem; height: 1rem; fill: none; stroke: var(--dawn); stroke-width: 1.8; stroke-linejoin: round; }
.nav__links { display: flex; align-items: center; gap: clamp(0.75rem, 3vw, 2rem); list-style: none; margin: 0; padding: 0; }
.nav__links a:not(.btn) {
  display: inline-flex; align-items: center; min-height: 2.75rem;
  color: var(--muted); text-decoration: none;
}
.nav__links a:not(.btn):hover { color: var(--ink); }

/* Hero */
.hero {
  position: relative; isolation: isolate; overflow: hidden;
  min-height: min(52rem, 100svh);
  display: flex; align-items: flex-start;
  padding: clamp(5rem, 14vh, 9rem) var(--gutter) 16rem;
}
.hero__copy { position: relative; max-width: 76rem; width: 100%; margin: 0 auto; }
.hero h1 {
  max-width: 13ch;
  font-size: clamp(2.75rem, 8vw, 6rem); line-height: 1.02; letter-spacing: -0.02em;
}
.lede { max-width: 36rem; margin-top: 1.75rem; color: var(--muted); font-size: 1.1875rem; line-height: 1.7; }
.hero__actions { display: flex; flex-wrap: wrap; align-items: center; gap: 0.75rem 1.75rem; margin-top: 2.5rem; }

/* Ambient background: the night, drawn as a hypnogram, rising into dawn */
.hero__glow {
  position: absolute; inset: auto -20% -40% 30%; height: 80%; z-index: -1;
  background: radial-gradient(closest-side, oklch(0.82 0.11 60 / 0.16), transparent);
}
.hero__night {
  position: absolute; left: 0; right: 0; bottom: 3rem; z-index: -1;
  width: 100%; height: clamp(9rem, 26vh, 14rem);
  fill: none; stroke-linejoin: round;
}
.hero__night .stages line { stroke: var(--rule); stroke-width: 1; stroke-dasharray: 2 6; vector-effect: non-scaling-stroke; }
.hero__night .night { stroke: var(--line); stroke-width: 2; vector-effect: non-scaling-stroke; }
.hero__night .wake { stroke: var(--dawn); stroke-width: 2.5; vector-effect: non-scaling-stroke; }

@media (prefers-reduced-motion: no-preference) {
  .hero__night .night { animation: draw 5s var(--ease) both; }
  .hero__night .wake { animation: draw 1.4s var(--ease) 4.2s both; }
  .hero__glow { animation: breathe 9s ease-in-out 4.5s infinite alternate both; }
  .hero__copy { animation: rise 900ms var(--ease) both; }
}
@keyframes draw { from { clip-path: inset(0 100% 0 0); } to { clip-path: inset(0 0 0 0); } }
@keyframes breathe { from { opacity: 1; } to { opacity: 0.45; } }
@keyframes rise { from { opacity: 0; transform: translateY(12px); } }

/* Testimonials strip */
.stories { max-width: 76rem; margin: 0 auto; padding: clamp(4rem, 10vw, 7rem) var(--gutter); }
.stories h2 { font-size: clamp(1.75rem, 4vw, 2.5rem); line-height: 1.15; max-width: 16ch; }
.stories__list {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(15rem, 1fr));
  gap: 3rem 2.5rem; list-style: none; margin: 3rem 0 0; padding: 0;
}
.stories figure { margin: 0; display: flex; flex-direction: column; height: 100%; }
.mini {
  width: 100%; height: 2.5rem; margin-bottom: 1.5rem;
  fill: none; stroke: var(--line); stroke-width: 1.5; stroke-linejoin: round;
}
.mini path { vector-effect: non-scaling-stroke; }
.mini .wake { stroke: var(--dawn); stroke-width: 2; }
.stories blockquote { margin: 0; flex: 1; font-size: 1.0625rem; line-height: 1.6; }
.stories figcaption { margin-top: 1.25rem; padding-top: 1rem; border-top: 1px solid var(--rule); color: var(--muted); font-size: 0.9375rem; }

/* Footer */
.footer { border-top: 1px solid var(--rule); background: var(--surface); }
.footer__line { display: block; width: 100%; height: 2.5rem; fill: none; stroke: var(--line); stroke-width: 1.5; stroke-linejoin: round; }
.footer__line path { vector-effect: non-scaling-stroke; }
.footer__line .wake { stroke: var(--dawn); stroke-width: 2; }
.footer__inner {
  display: flex; flex-wrap: wrap; align-items: baseline; gap: 0.5rem 2rem;
  max-width: 76rem; margin: 0 auto; padding: 2rem var(--gutter) 2.5rem;
  color: var(--muted); font-size: 0.9375rem;
}
.footer__inner .wordmark { min-height: 0; color: var(--ink); }
.footer__legal { margin-left: auto; }

